/* GHZ-2 scalability benchmark, regime 'unit', k = 2 gates.
 * Generated by scripts/run_benchmark.py — do not edit by hand. */
#define INV_SQRT2 0.70710678118654752440
#define DIM 4

extern double __VERIFIER_nondet_double(void);

int main() {
    double ar[DIM]; double ai[DIM];
    double br[DIM]; double bi[DIM];
    /* Fully symbolic initial state, constrained to unit norm
     * (assume band slightly tighter than the assert band so that
     * IEEE 754 rounding cannot produce spurious counterexamples). */
    ar[0] = __VERIFIER_nondet_double();
    ai[0] = __VERIFIER_nondet_double();
    __ESBMC_assume(ar[0] >= -1.001 && ar[0] <= 1.001);
    __ESBMC_assume(ai[0] >= -1.001 && ai[0] <= 1.001);
    ar[1] = __VERIFIER_nondet_double();
    ai[1] = __VERIFIER_nondet_double();
    __ESBMC_assume(ar[1] >= -1.001 && ar[1] <= 1.001);
    __ESBMC_assume(ai[1] >= -1.001 && ai[1] <= 1.001);
    ar[2] = __VERIFIER_nondet_double();
    ai[2] = __VERIFIER_nondet_double();
    __ESBMC_assume(ar[2] >= -1.001 && ar[2] <= 1.001);
    __ESBMC_assume(ai[2] >= -1.001 && ai[2] <= 1.001);
    ar[3] = __VERIFIER_nondet_double();
    ai[3] = __VERIFIER_nondet_double();
    __ESBMC_assume(ar[3] >= -1.001 && ar[3] <= 1.001);
    __ESBMC_assume(ai[3] >= -1.001 && ai[3] <= 1.001);
    double norm_in = 0.0;
    norm_in += ar[0]*ar[0] + ai[0]*ai[0];
    norm_in += ar[1]*ar[1] + ai[1]*ai[1];
    norm_in += ar[2]*ar[2] + ai[2]*ai[2];
    norm_in += ar[3]*ar[3] + ai[3]*ai[3];
    __ESBMC_assume(norm_in >= 0.9995 && norm_in <= 1.0005);

    /* gate: H */
    br[0] = INV_SQRT2 * (ar[0] + ar[2]);
    bi[0] = INV_SQRT2 * (ai[0] + ai[2]);
    br[2] = INV_SQRT2 * (ar[0] - ar[2]);
    bi[2] = INV_SQRT2 * (ai[0] - ai[2]);
    br[1] = INV_SQRT2 * (ar[1] + ar[3]);
    bi[1] = INV_SQRT2 * (ai[1] + ai[3]);
    br[3] = INV_SQRT2 * (ar[1] - ar[3]);
    bi[3] = INV_SQRT2 * (ai[1] - ai[3]);

    /* gate: CNOT(q0,q1) */
    ar[0] = br[0];
    ai[0] = bi[0];
    ar[1] = br[1];
    ai[1] = bi[1];
    ar[2] = br[3];
    ai[2] = bi[3];
    ar[3] = br[2];
    ai[3] = bi[2];

    double norm_out = 0.0;
    norm_out += ar[0]*ar[0] + ai[0]*ai[0];
    norm_out += ar[1]*ar[1] + ai[1]*ai[1];
    norm_out += ar[2]*ar[2] + ai[2]*ai[2];
    norm_out += ar[3]*ar[3] + ai[3]*ai[3];
    __ESBMC_assert(norm_out >= 0.999 && norm_out <= 1.001,
                   "GHZ-2: norm not preserved");
    return 0;
}